public Action inspect(AtmosphereResource r) {
    switch (r.getTransport()) {
        case LONG_POLLING:
            // Long polling requires explicit suspend
            // and resume on broadcast
            return doSuspend(r, false);
        case WEBSOCKET:
            // WebSocket requires explicit suspend
            // and resume on transport error
            return doSuspend(r, true);
        case AJAX:
            // Ajax requires explicit suspend
            // and resume on transport error
            return doSuspend(r, true);
        default:
            // Other transports do not require
            // any special handling
            return Action.CONTINUE;
    }
}

private Action doSuspend(AtmosphereResource r, boolean isDisconnect) {
    if (isDisconnect) {
        // Suspend the resource on transport error
        try {
            r.suspend();
        } catch (IllegalStateException e) {
            // Already suspended, log and continue
            LOG.trace("AtmosphereResource is already suspended, ignoring", e);
        }
    } else {
        // Suspend the resource on broadcast
        // and resume on broadcast
        r.suspend(new SuspendListener() {
            @Override
            public void onSuspend(AtmosphereResourceEvent event) {
                if (event.isCancelled()) {
                    // Suspension canceled, log and continue
                    LOG.trace("AtmosphereResource suspension canceled, ignoring", event.getException());
                } else {
                    // Resume the resource
                    r.resume();
                }
            }
        });
    }

    return Action.SUSPEND;
}

